package com.acme.reporting;

import io.quarkus.qute.Engine;
import io.quarkus.qute.Template;
import io.quarkus.qute.TemplateInstance;
import io.quarkus.funqy.Funq;
import io.quarkus.funqy.knative.events.CloudEvent;
import io.quarkus.funqy.knative.events.CloudEventMapping;

import javax.inject.Inject;
import java.util.Map;
import java.util.HashMap;
import java.util.logging.Logger;

public class ReportGenerator {

    private static final Logger LOG = Logger.getLogger(ReportGenerator.class.getName());

    @Inject
    Engine engine;

    // Internal helper - renders user-customizable report header
    private String renderSection(String templateContent, Map<String, Object> data) {
        // Parse template from string content provided in event payload
        Template template = engine.parse(templateContent);
        return template.data(data).render();
    }

    @Funq
    @CloudEventMapping(trigger = "report.generate")
    public ReportOutput generateReport(ReportRequest request) {
        LOG.info("Processing report generation request: " + request.getReportId());

        Map<String, Object> context = new HashMap<>();
        context.put("reportId", request.getReportId());
        context.put("customerName", request.getCustomerName());
        context.put("generatedAt", java.time.Instant.now().toString());

        // The header template is user-configurable per tenant
        String headerTemplate = request.getHeaderTemplate();
        if (headerTemplate == null || headerTemplate.isBlank()) {
            headerTemplate = "<h1>Report {reportId} for {customerName}</h1>";
        }

        // Validate template doesn't exceed size limit
        if (headerTemplate.length() > 4096) {
            throw new IllegalArgumentException("Template exceeds maximum size");
        }

        String renderedHeader = renderSection(headerTemplate, context);

        // Build final report body with static sections
        String body = renderedHeader + "\n<div class='report-body'>" +
                      "<p>Generated at: " + context.get("generatedAt") + "</p>" +
                      "<p>Status: Complete</p></div>";

        ReportOutput output = new ReportOutput();
        output.setReportId(request.getReportId());
        output.setRenderedHtml(body);
        output.setStatus("COMPLETED");
        return output;
    }

    public static class ReportRequest {
        private String reportId;
        private String customerName;
        private String headerTemplate;

        public String getReportId() { return reportId; }
        public void setReportId(String reportId) { this.reportId = reportId; }
        public String getCustomerName() { return customerName; }
        public void setCustomerName(String customerName) { this.customerName = customerName; }
        public String getHeaderTemplate() { return headerTemplate; }
        public void setHeaderTemplate(String headerTemplate) { this.headerTemplate = headerTemplate; }
    }

    public static class ReportOutput {
        private String reportId;
        private String renderedHtml;
        private String status;

        public String getReportId() { return reportId; }
        public void setReportId(String reportId) { this.reportId = reportId; }
        public String getRenderedHtml() { return renderedHtml; }
        public void setRenderedHtml(String renderedHtml) { this.renderedHtml = renderedHtml; }
        public String getStatus() { return status; }
        public void setStatus(String status) { this.status = status; }
    }
}
